/**
 * Generic numeric clamp — `Math.min(Math.max(n, lo), hi)`. Pure,
 * framework-free, SSR-safe. Extracted 2026-08-11 (P3.5 / D-04) from
 * byte-identical private copies in `team-challenge/lib/derive.ts` and
 * `team-progress-bar/lib/resolve-progress.ts`.
 */
export function clamp(n: number, lo: number, hi: number): number {
  return Math.min(Math.max(n, lo), hi);
}

/**
 * First letters of up to two name words → avatar initials fallback.
 * Empty (or whitespace-only) input returns `"?"`; a single word returns its
 * first two characters; two-or-more words return the first character of the
 * first word + the first character of the last word — all uppercased. Pure,
 * framework-free, SSR-safe, deterministic.
 *
 * Extracted 2026-08-11 (P3.5 / D-04) from two behaviorally-identical private
 * copies: `team-challenge/parts/team-member-stack.tsx`'s `initials(name)` and
 * `team-task-claim/lib/members.ts`'s `initialsFor(member, fallbackId)` (the
 * latter is a member-resolution wrapper that now calls this core directly).
 */
export function initialsFromName(name: string): string {
  const trimmed = name.trim();
  if (trimmed === "") return "?";
  const parts = trimmed.split(/\s+/).filter(Boolean);
  if (parts.length === 1) return parts[0]!.slice(0, 2).toUpperCase();
  return (parts[0]![0]! + parts[parts.length - 1]![0]!).toUpperCase();
}

"use client";

import * as React from "react";

/**
 * Keep a ref in sync with the latest `value`, assigned inside a `useEffect`
 * (never during render — not a `setState`, so it stays StrictMode-safe).
 * Read `.current` from event handlers, timers, or other effects so a fresh
 * inline callback/prop (a new identity every render) never has to be a
 * dependency of — and never re-subscribes — an observer/listener/timer keyed
 * on other, more stable deps.
 *
 * Extracted 2026-08-11 (P3.5 / D-04) from ~15 independent copies of this
 * exact idiom across the pack's headless `Root` providers and telemetry
 * hooks (`const xRef = useRef(x); useEffect(() => { xRef.current = x; })`,
 * with or without an explicit `[x]` dependency array — both variants
 * converge to the same steady-state ref value, so a single shared
 * implementation running every render is a strict, behavior-preserving
 * superset of both).
 */
export function useLatestRef<T>(value: T): React.RefObject<T> {
  const ref = React.useRef(value);
  React.useEffect(() => {
    ref.current = value;
  });
  return ref;
}

